/*
 * A090964  Permutation of natural numbers generated by 2-rowed array shown
 *          below.
 * https://oeis.org/A090964
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 71, u16 n <= 71, u32 n <= 71, u64 n <= 71, u128 n <= 71,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 *  Implements OEIS A090964.
 *  The sequence satisfies:
 *    a(0) = 1, a(1) = 4
 *    for n > 1 : a(n) = a(n-8) + 8
 *
 *  This is equivalent to the following closed form,
 *  which is used for constant‑time evaluation of any n ≥ 0:
 *
 *    let r = n mod 8
 *    if n == 0          → 1
 *    else if r == 0     → n - 1
 *    else if r == 1     → n + 3
 *    else               → n - r + base[r]
 *
 *  where base[0..7] = {1,4,2,5,3,8,6,9}  (the first eight terms).
 *  The extra case for r == 0 handles n = 0, 8, 16, …
 *
 *  The function is fully O(1) and works for all n that fit in idx_t.
 */
seq_t a(idx_t n)
{
    if (n == 0u)
        return (seq_t)1;                     /* a(0) */

    uint64_t r = n % 8u;

    /* r == 0 : a(8k) = 8k - 1 for k ≥ 1  (a(0) already handled) */
    if (r == 0u)
        return (seq_t)(n - 1u);

    /* r == 1 : a(8k+1) = 8k + 4  */
    if (r == 1u)
        return (seq_t)(n + 3u);

    /* For r = 2…7 use the base values with a simple offset */
    static const seq_t base[8] = {1, 4, 2, 5, 3, 8, 6, 9};
    /* n - r removes the offset of the current block,
       adding base[r] places the value within the block. */
    return (seq_t)(n - r + base[r]);
}
